// Characterization tests: pin the current client-visible behaviour of the HTTP API,
// including quirks (e.g. 200 for unknown orders). Change them only deliberately.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 2.5, pear: 10, gold: 60, cent: 0.01 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order and returns 201 with id, items, total', async () => {
  const items = [{ sku: 'apple', qty: 2 }]
  const r = await json(await post({ items }))
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(Object.keys(r.body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof r.body.id, 'string')
  assert.deepEqual(r.body.items, items)
  assert.equal(r.body.total, 5)
})

test('ids are strings and unique per order', async () => {
  const a = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  const b = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  assert.notEqual(a.body.id, b.body.id)
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('total sums price * qty across items', async () => {
  const r = await json(await post({ items: [{ sku: 'apple', qty: 2 }, { sku: 'pear', qty: 3 }] }))
  assert.equal(r.body.total, 35)
})

test('total is floored to a whole number', async () => {
  const r = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  assert.equal(r.body.total, 2)
})

test('no discount when the total is exactly 100', async () => {
  const r = await json(await post({ items: [{ sku: 'pear', qty: 10 }] }))
  assert.equal(r.body.total, 100)
})

test('10% discount applies when the total is over 100', async () => {
  const r = await json(await post({ items: [{ sku: 'pear', qty: 11 }] }))
  assert.equal(r.body.total, 99)
})

test('discount is applied before flooring', async () => {
  // 60 * 2 = 120 -> 108 ; 60 * 2 + 2.5 = 122.5 -> 110.25 -> 110
  assert.equal((await json(await post({ items: [{ sku: 'gold', qty: 2 }] }))).body.total, 108)
  const r = await json(await post({ items: [{ sku: 'gold', qty: 2 }, { sku: 'apple', qty: 1 }] }))
  assert.equal(r.body.total, 110)
})

test('pricing is consulted for each item sku', async () => {
  calls.length = 0
  await post({ items: [{ sku: 'apple', qty: 1 }, { sku: 'pear', qty: 1 }] })
  assert.deepEqual(calls, ['apple', 'pear'])
})

test('POST /orders with missing, empty or non-array items returns 400', async () => {
  for (const body of [{}, { items: [] }, { items: 'apple' }, { items: null }]) {
    const r = await json(await post(body))
    assert.equal(r.status, 400, JSON.stringify(body))
    assert.deepEqual(r.body, { error: 'items required' })
  }
})

test('POST /orders with malformed JSON returns 400', async () => {
  const r = await json(await post(undefined, '{not json'))
  assert.equal(r.status, 400)
  assert.deepEqual(r.body, { error: 'items required' })
})

test('POST /orders with empty body returns 400', async () => {
  const r = await json(await post(undefined, ''))
  assert.equal(r.status, 400)
  assert.deepEqual(r.body, { error: 'items required' })
})

test('invalid orders are not stored', async () => {
  const before = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  await post({ items: [] })
  const after = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  assert.equal(Number(after.body.id), Number(before.body.id) + 1)
})

test('GET /orders/:id returns the stored order with 200', async () => {
  const created = await json(await post({ items: [{ sku: 'pear', qty: 2 }] }))
  const r = await json(await fetch(`${base}/orders/${created.body.id}`))
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created.body)
})

test('GET /orders/:id for an unknown id returns 200 with an error body (not 404)', async () => {
  const r = await json(await fetch(`${base}/orders/does-not-exist`))
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
})

test('unknown routes and methods return 404 "no route"', async () => {
  const cases = [
    ['GET', '/'],
    ['GET', '/orders'],
    ['GET', '/orders/'],
    ['GET', '/orders/1/items'],
    ['PUT', '/orders/1'],
    ['DELETE', '/orders/1'],
    ['POST', '/orders/1'],
    ['GET', '/other'],
  ]
  for (const [method, path] of cases) {
    const r = await json(await fetch(base + path, { method }))
    assert.equal(r.status, 404, `${method} ${path}`)
    assert.deepEqual(r.body, { error: 'no route' }, `${method} ${path}`)
  }
})

test('query strings are ignored when routing', async () => {
  const created = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  const r = await json(await fetch(`${base}/orders/${created.body.id}?x=1`))
  assert.deepEqual(r.body, created.body)
})
